ALTER TABLE course_records ADD COLUMN active INTEGER NOT NULL DEFAULT 1;
CREATE TABLE record_proposals(id TEXT PRIMARY KEY, category TEXT NOT NULL, record_id INTEGER NOT NULL, expected_version INTEGER NOT NULL, payload TEXT NOT NULL, reason TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), identity_confirmed INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE record_revisions(id INTEGER PRIMARY KEY, category TEXT NOT NULL, record_id INTEGER NOT NULL, version INTEGER NOT NULL, before_payload TEXT NOT NULL, after_payload TEXT NOT NULL, operation TEXT NOT NULL, reason TEXT NOT NULL, actor_id INTEGER NOT NULL REFERENCES users(id), created_at INTEGER NOT NULL, source_row_id INTEGER NOT NULL REFERENCES import_rows(id), UNIQUE(category,record_id,version));
